        result.setResourceId(resource.getId());
        result.setResKey(resource.getResKey());
        try {
            Expression urlExpr = parser.parseExpression(resource.getUrlExpr());
            String url = urlExpr.getValue(context, String.class);
            result.setResultUrl(url);
            result.setStatus("SUCCESS");
        } catch (Exception e) {
